/**
 * The bundled Lucide set (SPEC 11 §12).
 *
 * "The full Lucide set (ISC licence) bundled as an SVG sprite" — but this project does not
 * have a sprite and cannot use one: the preview paints a canvas and the export writes ASS
 * drawing commands, so both need geometry, not markup. The set is therefore bundled as data
 * (`/assets/icons/lucide.json`, generated by `scripts/generate-icons.mjs`) and turned into
 * geometry by `iconGeometry` in `icons.ts`.
 *
 * Why a committed asset and not the `lucide-react` dependency: that package is 1556 ES
 * modules of React components. Importing it from a compositor used by the *main process* of
 * an Electron app would pull React into a build that has no renderer, and a bundler would
 * ship all 1556 modules to draw three icons. The asset is 240 KB of plain data, it diffs one
 * icon per line, and its licence travels with it — the same arrangement as
 * `/assets/whisper-models.json` and `/assets/provider-presets.json`.
 *
 * **Offline.** Nothing here opens a socket. The set is whatever shipped in the binary, which
 * is what "offline" has to mean for an editor that is expected to work on a shoot with no
 * network.
 */
import storedIcons from '../../../assets/icons/lucide.json';
import {
  drawableIconNames,
  iconLibraryFromStored,
  searchIcons,
  type IconShape,
  type StoredIconLibrary,
} from './icons.js';

/**
 * Every icon this build can draw, name → children.
 *
 * Converted once, at module load: 1555 entries of a few children each is a few milliseconds
 * of JSON walking, and doing it here rather than per frame is the difference between an icon
 * that costs nothing to render twice and one that parses a path on every repaint.
 */
export const ICON_LIBRARY: Readonly<Record<string, readonly IconShape[]>> = Object.freeze(
  iconLibraryFromStored(storedIcons as unknown as StoredIconLibrary),
);

/**
 * The names the picker may offer: exactly those whose geometry converts.
 *
 * Sorted, and computed once. 14 of Lucide's 1555 icons contain a genuinely elliptical arc,
 * which this build refuses by name rather than drawing approximately, so they are absent here
 * and cannot be picked. A tile that draws nothing when clicked is indistinguishable from a
 * broken application.
 */
export const ICON_NAMES: readonly string[] = Object.freeze(drawableIconNames(ICON_LIBRARY));

/** Search the bundled set, for the picker's filter box. */
export function searchIconLibrary(query: string): string[] {
  return searchIcons(ICON_NAMES, query);
}

/** How many icons this build ships, for the picker's label and the docs. */
export const ICON_COUNT = ICON_NAMES.length;
